def find_distance(start, targets):
    distances = {start: 0}
    queue = deque([start])
    found_targets = {}

    while queue:
        curr = queue.popleft()
        if curr in targets:
            found_targets[curr] = distances[curr]
            if len(found_targets) == len(targets):
                break

