# Actually, let's try BFS again but with a limit on the number of iterations.
# Or better, let's try to find paths for each target separately using bidirectional BFS.

def bidirectional_bfs(start, target):
    if start == target:
        return 0

    forward_visited = {start: 0}
    backward_visited = {target: 0}
    forward_queue = deque([start])
    backward_queue = deque([target])

    for _ in range(10000): # Limit the number of steps
        # Forward step
        if forward_queue:
            curr = forward_queue.popleft()
            for neighbor in get_neighbors(curr):
                if neighbor in backward_visited:
                    return (forward_visited[curr] + 1 + backward_visited[neighbor]) % 2
                if neighbor not in forward_visited:
                    forward_visited[neighbor] = forward_visited[curr] + 1
                    forward_queue.append(neighbor)

        # Backward step
        if backward_queue:
            curr = backward_queue.popleft()
            for neighbor in get_neighbors(curr):
                if neighbor in forward_visited:
                    return (backward_visited[curr] + 1 + forward_visited[neighbor]) % 2
                if neighbor not in backward_visited:
                    backward_visited[neighbor] = backward_visited[curr] + 1
                    backward_queue.append(neighbor)

    return None

